import{_ as t,l as d,o as e,c as i,v as o,p as l,x as n,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"按秩与路径压缩","description":"","frontmatter":{"title":"按秩与路径压缩","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/uf-rank-compress.md","filePath":"cs/uf-rank-compress.md","lastUpdated":1789023840000}'),h={name:"cs/uf-rank-compress.md"};function m(f,a,A,u,_,E){const r=d("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="按秩与路径压缩" tabindex="-1">按秩与路径压缩 <a class="header-anchor" href="#按秩与路径压缩" aria-label="Permalink to &quot;按秩与路径压缩&quot;">​</a></h1><div class="epigraph"><p>矮树挂到高树上，高度有对数顶；再把路上的点直接接到根，摊还才掉到反 Ackermann。</p><footer>—— 据 Tarjan, Efficiency of a Good But Not Linear Set Union Algorithm, JACM 1975；Cormen, Leiserson, Rivest and Stein 第 21 章 整理</footer></div><p><a href="/cs/union-find">上一课</a>已经给出父指针森林、<code>find</code>/<code>union</code>，并点名按秩加压缩、摊还 \\(\\alpha(n)\\)，却把两条技术的不变式捆在一起。本课不重讲分区 ADT。缺口是把它们拆开：只按秩（或按大小）时高度 \\(O(\\log n)\\)；只压缩时最坏仍可差；合在一起秩是高度上界且压缩不增加秩。图表示下一课要存边，本课仍不存边。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素 union 把一棵树挂到另一棵根上，链长可以 \\(\\Theta(n)\\)。按秩：根存一个整数 \\(\\mathrm{rank}\\)，union 时秩小的根挂到秩大的；仅当两秩相等时赢家秩加一。不变式：\\(\\mathrm{rank}[x]\\) 不小于子树高度的一个上界，且沿父严格降。缺口是证明<strong>秩一旦写出，压缩不得把秩改大</strong>，否则上界烂掉。</p><p>路径压缩：<code>find</code> 把沿途节点的父改成根（两趟或递归返回时改）。深度变 1，但秩字段保持原值——它不再等于真实高度，只是上界。</p><p><span class="marginnote">只压缩不按秩，Tarjan 仍给出摊还界，但实现上两条都做几乎零成本。主干两者都开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>Link(x,y)</code> 两根：若 <code>rank[x]&lt;rank[y]</code> 则 <code>parent[x]=y</code>；对称；相等则 <code>parent[y]=x</code>，<code>rank[x]++</code>。<code>Find</code> 压缩不改 <code>rank</code>。按大小合并把 <code>rank</code> 换成子树规模，挂小到大，无压缩时高度 \\(O(\\log n)\\) 同样成立。</p>',9)),(e(),l(p,null,{default:n(()=>[c(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E4%B8%A4%E6%A0%B9%22%5D%20--%3E%20CMP%5B%22%E6%AF%94%E7%A7%A9%22%5D%0A%20%20CMP%20--%3E%20HANG%5B%22%E7%9F%AE%E6%8C%82%E9%AB%98%22%5D%0A%20%20F%5B%22find%20%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20CMPR%5B%22%E6%B2%BF%E9%80%94%E7%88%B6%20%E2%86%90%20%E6%A0%B9%22%5D%0A%20%20CMPR%20--%3E%20RANK%5B%22%E7%A7%A9%E5%AD%97%E6%AE%B5%E4%B8%8D%E5%8A%A8%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>调用方仍不得缓存旧根：压缩和 union 都会改代表。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了秩上界，一棵秩为 \\(k\\) 的树至少 \\(2^k\\) 个节点（归纳：秩加一发生在两棵同秩树合并）。故最大秩 \\(O(\\log n)\\)，无压缩时 <code>find</code> 为 \\(O(\\log n)\\)。压缩把已经付过的路径摊到以后的 <code>find</code>。\\(\\alpha(n)\\) 本课仍不展开定义：合同写成「摊还几乎常数，单次最坏可较长」。</p><p>与动态数组摊还不同：这里势能跟节点到根的距离、秩有关，Tarjan 的会计更细。邻接表课不需要这个势能。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入可持久化、不支持删边。也不把 \\(\\alpha(n)\\) 写成最坏 \\(O(1)\\)。图若还要枚举边，并查集不够——下一课邻接表与矩阵。</p><p>后课默认：实现并查集时按秩（或按大小）加压缩都打开。要存边集，换图表示。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>按秩给出高度 \\(O(\\log n)\\) 上界；压缩不改秩字段。</li><li>合在一起摊还 \\(\\alpha(n)\\)；代表仍会变。</li><li>边的布局是下一课邻接表与矩阵。</li><li>出处：Tarjan, <em>JACM</em>, 1975；Cormen et al. 第 21 章。</li></ul>',9))])}const T=t(h,[["render",m]]);export{B as __pageData,T as default};
